def forward(groups):
    date_part = groups[0]  # YYMMDD
    time_part = groups[1]  # HHMMSS
    packed = int(date_part) * 1000000 + int(time_part)
    return {'stored': [packed], 'layout': []}

def inverse(record):
    packed = record['stored'][0]
    date_part = f"{packed // 1000000:06d}"
    time_part = f"{packed % 1000000:06d}"
    return f"{date_part} {time_part}"
